import { useCallback, useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({
    results: [],
    phase: "idle",
  });

  const valueRef = useRef(value);
  const viewRef = useRef(view);
  const searchRef = useRef(search);
  const minCharsRef = useRef(minChars);
  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);
  const mountedRef = useRef(true);

  valueRef.current = value;
  searchRef.current = search;
  minCharsRef.current = minChars;

  const commitView = useCallback((nextView) => {
    viewRef.current = nextView;
    setView(nextView);
  }, []);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const resetForShortQuery = useCallback(() => {
    clearTimer();

    const latestRequest = latestRequestRef.current;
    latestRequestRef.current = null;

    if (latestRequest?.status === "inflight") {
      latestRequest.status = "aborted";
      if (!latestRequest.controller.signal.aborted) {
        latestRequest.controller.abort();
      }
    }

    if (mountedRef.current) {
      commitView({
        results: [],
        phase: "idle",
      });
    }
  }, [clearTimer, commitView]);

  const startRequest = useCallback(
    (query, force = false) => {
      clearTimer();

      if (!mountedRef.current || query !== valueRef.current.trim()) {
        return;
      }

      if (query.length < minCharsRef.current) {
        resetForShortQuery();
        return;
      }

      const previousRequest = latestRequestRef.current;

      if (
        !force &&
        previousRequest?.query === query &&
        (previousRequest.status === "inflight" ||
          previousRequest.status === "success")
      ) {
        return;
      }

      const previousView = viewRef.current;
      let fallbackPhase = "idle";

      if (
        previousView.phase === "empty" ||
        previousView.phase === "success"
      ) {
        fallbackPhase = previousView.phase;
      } else if (
        previousView.phase === "loading" &&
        previousRequest?.fallbackPhase
      ) {
        fallbackPhase = previousRequest.fallbackPhase;
      }

      if (previousRequest) {
        latestRequestRef.current = null;
        previousRequest.status = "aborted";

        if (!previousRequest.controller.signal.aborted) {
          previousRequest.controller.abort();
        }
      }

      const controller = new AbortController();
      const request = {
        query,
        controller,
        status: "inflight",
        fallbackPhase,
        fallbackResults: previousView.results,
      };

      latestRequestRef.current = request;

      commitView({
        results: previousView.results,
        phase: "loading",
      });

      const isCurrentRequest = () =>
        mountedRef.current &&
        latestRequestRef.current === request &&
        request.status === "inflight";

      const handleSuccess = (results) => {
        if (!isCurrentRequest()) {
          return;
        }

        if (controller.signal.aborted) {
          request.status = "aborted";
          commitView({
            results: request.fallbackResults,
            phase: request.fallbackPhase,
          });
          return;
        }

        request.status = "success";
        commitView({
          results,
          phase: results.length === 0 ? "empty" : "success",
        });
      };

      const handleFailure = (error) => {
        if (!isCurrentRequest()) {
          return;
        }

        if (controller.signal.aborted || error?.name === "AbortError") {
          request.status = "aborted";
          commitView({
            results: request.fallbackResults,
            phase: request.fallbackPhase,
          });
          return;
        }

        request.status = "failed";
        commitView({
          results: [],
          phase: "error",
        });
      };

      try {
        Promise.resolve(
          searchRef.current(query, { signal: controller.signal }),
        ).then(handleSuccess, handleFailure);
      } catch (error) {
        handleFailure(error);
      }
    },
    [clearTimer, commitView, resetForShortQuery],
  );

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      clearTimer();

      const latestRequest = latestRequestRef.current;
      latestRequestRef.current = null;

      if (latestRequest?.status === "inflight") {
        latestRequest.status = "aborted";
        if (!latestRequest.controller.signal.aborted) {
          latestRequest.controller.abort();
        }
      }
    };
  }, [clearTimer]);

  useEffect(() => {
    clearTimer();

    const query = value.trim();

    if (query.length < minChars) {
      resetForShortQuery();
      return undefined;
    }

    const timerId = setTimeout(() => {
      if (timerRef.current !== timerId) {
        return;
      }

      timerRef.current = null;

      if (valueRef.current.trim() === query) {
        startRequest(query);
      }
    }, debounceMs);

    timerRef.current = timerId;

    return () => {
      clearTimeout(timerId);
      if (timerRef.current === timerId) {
        timerRef.current = null;
      }
    };
  }, [
    value,
    debounceMs,
    minChars,
    clearTimer,
    resetForShortQuery,
    startRequest,
  ]);

  const handleChange = useCallback((event) => {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);
  }, []);

  const handleRetry = useCallback(() => {
    const query = valueRef.current.trim();

    if (query.length < minCharsRef.current) {
      resetForShortQuery();
      return;
    }

    startRequest(query, true);
  }, [resetForShortQuery, startRequest]);

  const statusText =
    view.phase === "loading"
      ? "Searching..."
      : view.phase === "empty"
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{statusText}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          <span>Something went wrong</span>
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
